    requires substring != ""
    requires string.Length >= 0
    ensures count >= 0
    ensures count == CountOccurrences(string, substring)

    // Helper function to count occurrences of substring in string
    function CountOccurrences(string: string, substring: string): int
        reads string, substring
        decreases string.Length // Assuming the length of the string decreases with each recursive call
    {
        if string.Length < substring.Length {
            return 0;
        }
        if string.StartsWith(substring) {
            return 1 + CountOccurrences(string[1..], substring);
        }
        return CountOccurrences(string[1..], substring);
    }
